insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('life-timeline-review', 'Life Timeline Review', 'worksheet'::resource_kind, 'A line across the page marked with the turning points of the client''s life, high and low.', 'Give the client and clinician a shared map of where the present difficulties sit in a longer story.', array['Adults', 'Teens']::text[], 'Full session', 'Draw one long line and let the client place events above it for good and below it for hard. Ask about the gaps as much as the marks; a quiet decade is often where something was being held. Keep the pace theirs and stop at any point that is too much for today; the timeline can be finished later.', '[{"id": "f0", "type": "textarea", "label": "The events I would put above the line"}, {"id": "f1", "type": "textarea", "label": "The events I would put below the line"}, {"id": "f2", "type": "textarea", "label": "A stretch with nothing on it, and what was going on then"}, {"id": "f3", "type": "textarea", "label": "The turning point that matters most to what I am dealing with now"}, {"id": "f4", "type": "textarea", "label": "A strength I can see running through the line"}, {"id": "f5", "type": "textarea", "label": "What I want the next part of the line to look like"}]'::jsonb, array['narrative', 'life review', 'formulation']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('adult-wind-down-plan', 'Adult Wind-Down Plan', 'worksheet'::resource_kind, 'The last hour before bed planned step by step, with screens, worry and caffeine each given a cutoff.', 'Give an adult a predictable path to sleep instead of a nightly negotiation with the phone.', array['Adults', 'Teens']::text[], '15 minutes', 'Start from the wake time the client needs and work backward to fix the bedtime. The plan is only as good as the screen cutoff, so agree where the phone will physically be. Pair with the sleep diary when the client wants evidence; most see the change within two weeks if the plan is the same every night.', '[{"id": "f0", "type": "textarea", "label": "The time I need to be asleep, working back from when I must be up"}, {"id": "f1", "type": "textarea", "label": "Caffeine cutoff"}, {"id": "f2", "type": "textarea", "label": "Screen cutoff, and where the phone goes"}, {"id": "f3", "type": "textarea", "label": "The three steps of my wind-down, in order"}, {"id": "f4", "type": "textarea", "label": "What I will do with worries that arrive in bed (write them down for tomorrow)"}, {"id": "f5", "type": "textarea", "label": "What I will do if I am still awake after twenty minutes"}, {"id": "f6", "type": "textarea", "label": "How the first week went"}]'::jsonb, array['sleep', 'routines', 'habits']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('money-stress-map', 'Money Stress Map', 'worksheet'::resource_kind, 'Separates the parts of a money worry that are facts, decisions, feelings and fears.', 'Bring some order to a stress that usually arrives as one undifferentiated dread.', array['Adults']::text[], '25 minutes', 'You are not a financial adviser and the sheet does not give money advice; it sorts the worry so the client can act on the parts that are actionable and feel the parts that are feelings. Watch for shame, which stops people opening envelopes. The next-step prompt should be tiny: open one letter, make one call.', '[{"id": "f0", "type": "textarea", "label": "The money worry, as it comes to me"}, {"id": "f1", "type": "textarea", "label": "The facts I actually know (numbers, dates, who I owe)"}, {"id": "f2", "type": "textarea", "label": "The facts I have been avoiding finding out"}, {"id": "f3", "type": "textarea", "label": "The decisions that are mine to make"}, {"id": "f4", "type": "textarea", "label": "The feelings underneath (shame, fear, anger, grief)"}, {"id": "f5", "type": "textarea", "label": "One small step this week"}, {"id": "f6", "type": "textarea", "label": "Who I could talk to about the practical side"}]'::jsonb, array['money', 'stress', 'problem solving']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('loneliness-action-plan', 'Loneliness Action Plan', 'worksheet'::resource_kind, 'A week of small, specific moves toward people, chosen from the client''s own life rather than from advice.', 'Turn a vague wish for more connection into three concrete contacts this week.', array['Adults', 'Teens']::text[], '20 minutes', 'Start from the map of who is already there, however thin, before inventing new groups. Contacts should be small and specific: a message, a coffee, showing up at the same place twice. Plan for the anxiety that arrives before each one, and treat the plan as an experiment to review, not a test to pass.', '[{"id": "f0", "type": "textarea", "label": "People I already know who I have let drift"}, {"id": "f1", "type": "textarea", "label": "Places I go where the same faces appear"}, {"id": "f2", "type": "textarea", "label": "Three contacts I will make this week (who, how, when)"}, {"id": "f3", "type": "textarea", "label": "What my mind says will happen"}, {"id": "f4", "type": "textarea", "label": "What actually happened"}, {"id": "f5", "type": "textarea", "label": "Something I could join where I would see the same people weekly"}, {"id": "f6", "type": "textarea", "label": "The contact I will repeat next week"}]'::jsonb, array['loneliness', 'connection', 'behavioral activation']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('session-goals-tracker', 'Session Goals Tracker', 'worksheet'::resource_kind, 'Two or three goals set at the start of therapy, rated each session, with a note on what moved them.', 'Keep the work pointed at what the client came for and make progress visible to both of you.', array['Adults', 'Teens']::text[], '5 minutes per session', 'Set the goals in the first sessions in the client''s words and keep them to three. Rate them briefly at the start of each session; the rating matters less than the conversation about what moved it. Revisit and rewrite the goals when they stop fitting, which is itself progress worth noting.', '[{"id": "f0", "type": "textarea", "label": "Goal one, in my words"}, {"id": "f1", "type": "textarea", "label": "Goal two"}, {"id": "f2", "type": "textarea", "label": "Goal three"}, {"id": "f3", "type": "textarea", "label": "Today''s ratings (0-10 for each)"}, {"id": "f4", "type": "textarea", "label": "What moved a rating this week, up or down"}, {"id": "f5", "type": "textarea", "label": "A goal that no longer fits, and what would replace it"}]'::jsonb, array['session structure', 'goal setting', 'review']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('thought-feeling-behavior-triangle', 'Thought-Feeling-Behavior Triangle', 'cbt'::resource_kind, 'A triangle with a recent situation''s thoughts, feelings and actions at the corners, and arrows showing how each fed the others.', 'Teach the basic CBT model on the client''s own example rather than an abstract one.', array['Adults', 'Teens', 'Children']::text[], '15 minutes', 'Use it in the first sessions, drawn large, with a mild recent example. The arrows are the teaching: ask which corner the client could most easily change, since that is where the work will start. Keep the drawing and refer back to it whenever the model is needed again.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "What went through my mind"}, {"id": "f2", "type": "textarea", "label": "What I felt (emotions, and in my body)"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "Which corner fed which (draw the arrows)"}, {"id": "f5", "type": "textarea", "label": "The corner I could most easily change next time"}]'::jsonb, array['core CBT', 'psychoeducation', 'formulation']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('catastrophe-scale', 'Catastrophe Scale', 'cbt'::resource_kind, 'A 0 to 100 scale of bad events, with the client''s current worry placed among them.', 'Restore a sense of proportion by putting the feared outcome next to genuinely worse ones.', array['Adults', 'Teens']::text[], '15 minutes', 'Have the client fill the top of the scale with the worst things they can imagine happening to anyone, then the middle, then place the current worry. Most worries land far lower than they felt. The point is not to dismiss the worry but to size it; ask what the client would do if it actually happened.', '[{"id": "f0", "type": "textarea", "label": "The worst things I can imagine (90-100)"}, {"id": "f1", "type": "textarea", "label": "Very bad things (60-80)"}, {"id": "f2", "type": "textarea", "label": "Bad but survivable things (20-50)"}, {"id": "f3", "type": "textarea", "label": "Where my current worry sits, honestly"}, {"id": "f4", "type": "textarea", "label": "Where it felt like it sat before I did this"}, {"id": "f5", "type": "textarea", "label": "What I would actually do if it happened"}]'::jsonb, array['thinking traps', 'perspective', 'anxiety']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('belief-cost-benefit-sheet', 'Belief Cost-Benefit Sheet', 'cbt'::resource_kind, 'Weighs what a long-held belief does for the client against what it costs, before deciding whether to challenge it.', 'Build motivation to loosen a belief by examining its usefulness rather than its truth.', array['Adults', 'Teens']::text[], '20 minutes', 'Useful when a belief is obviously unhelpful but feels true, since arguing truth goes nowhere. Take the benefits seriously; beliefs like I must always be strong have kept the client going. The costs column is where the client''s own motivation appears. Finish with a modified version to try, not a rejection.', '[{"id": "f0", "type": "textarea", "label": "The belief, in my words"}, {"id": "f1", "type": "textarea", "label": "What it has done for me"}, {"id": "f2", "type": "textarea", "label": "What it costs me"}, {"id": "f3", "type": "textarea", "label": "What it costs the people around me"}, {"id": "f4", "type": "textarea", "label": "How much I believe it (0-100%)"}, {"id": "f5", "type": "textarea", "label": "A modified version I could try this week"}]'::jsonb, array['core beliefs', 'belief change', 'motivation']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('coping-statements-card', 'Coping Statements Card', 'cbt'::resource_kind, 'A pocket card of short, believable statements for the moments the client most often loses their footing.', 'Give the client rehearsed words for the moment, written while calm.', array['Adults', 'Teens']::text[], '15 minutes to build', 'The statements must be believable to the client, not cheerful; this has happened before and passed beats everything is fine. Write them for specific moments the client names. Read them aloud in session so the client has heard their own voice say them. Review after a week and cut any that felt false in the moment.', '[{"id": "f0", "type": "textarea", "label": "The moments I most need something to say to myself"}, {"id": "f1", "type": "textarea", "label": "A statement for each, believable to me"}, {"id": "f2", "type": "textarea", "label": "What I say to myself now in those moments"}, {"id": "f3", "type": "textarea", "label": "The statement I will keep on my phone lock screen"}, {"id": "f4", "type": "textarea", "label": "Which statements held up this week, and which felt false"}]'::jsonb, array['coping skills', 'self-talk', 'core CBT']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('mastery-and-pleasure-ratings', 'Mastery and Pleasure Ratings', 'cbt'::resource_kind, 'A day''s activities rated for the sense of achievement and the enjoyment each one gave.', 'Show the client that achievement and enjoyment come from different activities, and that both are already present in small amounts.', array['Adults', 'Teens']::text[], 'One week', 'Rate mastery and pleasure separately for each activity, on a scale that makes small values visible. Clients with low mood typically find that mastery is present in things they discounted as chores. Use the results to plan a week with a deliberate balance rather than defaulting to what feels urgent.', '[{"id": "f0", "type": "textarea", "label": "Date"}, {"id": "f1", "type": "textarea", "label": "Activity (hour by hour, or the main ones)"}, {"id": "f2", "type": "textarea", "label": "Mastery: sense of achievement (0-10)"}, {"id": "f3", "type": "textarea", "label": "Pleasure: enjoyment (0-10)"}, {"id": "f4", "type": "textarea", "label": "The activity with the most surprising rating"}, {"id": "f5", "type": "textarea", "label": "What I will add next week for mastery"}, {"id": "f6", "type": "textarea", "label": "What I will add for pleasure"}]'::jsonb, array['behavioral activation', 'depression', 'monitoring']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('sweet-spot-exercise', 'Sweet Spot Exercise', 'act'::resource_kind, 'The client recalls a moment of real vitality in detail and draws out the values it reveals.', 'Find values through a lived moment rather than a list.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Ask for a moment, recent or old, when life felt rich, and let the client describe it sense by sense while you listen for the values inside it. Reflect them back as qualities of action, not as feelings. In groups, pairs can interview each other. Follow with one small action this week that carries the same quality.', '[{"id": "f0", "type": "textarea", "label": "The moment, described in detail"}, {"id": "f1", "type": "textarea", "label": "What I was doing, and who was there"}, {"id": "f2", "type": "textarea", "label": "What made it matter"}, {"id": "f3", "type": "textarea", "label": "The qualities I was living out (curiosity, care, courage, play)"}, {"id": "f4", "type": "textarea", "label": "Where those qualities are missing in my week now"}, {"id": "f5", "type": "textarea", "label": "One small action this week with the same quality"}]'::jsonb, array['values', 'vitality', 'core ACT']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('expansion-practice', 'Expansion Practice', 'act'::resource_kind, 'A four-step guided practice for making room for a difficult feeling in the body: observe, breathe, allow, expand.', 'Help the client hold a feeling without fighting it, so it can move.', array['Adults', 'Teens']::text[], '10 minutes', 'Guide it slowly with a feeling of moderate strength the client brings in. Observe the sensation''s location and edges, breathe into and around it, allow it to be there, and imagine space opening around it. The client is not trying to make the feeling go; if it changes, note that as a bonus. Record the practice for home use.', '[{"id": "f0", "type": "textarea", "label": "The feeling I brought to this"}, {"id": "f1", "type": "textarea", "label": "Where it sits in my body, and its size and shape"}, {"id": "f2", "type": "textarea", "label": "What breathing into it was like"}, {"id": "f3", "type": "textarea", "label": "What allowing it was like"}, {"id": "f4", "type": "textarea", "label": "What happened as I made room"}, {"id": "f5", "type": "textarea", "label": "When I will use this in the week"}]'::jsonb, array['acceptance', 'willingness', 'mindfulness']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('quicksand-metaphor-sheet', 'Quicksand Metaphor Sheet', 'act'::resource_kind, 'Explores the metaphor of struggling in quicksand: the harder the fight, the deeper the sink.', 'Help the client see how struggling with a feeling makes it worse, and what lying back would look like.', array['Adults', 'Teens']::text[], '15 minutes', 'Tell the metaphor plainly: in quicksand, the survival move is to spread out and lie back, which is the opposite of what instinct says. Then ask what the client''s struggling looks like and what lying back would mean for their feeling. Do not over-explain; let the client make the link.', '[{"id": "f0", "type": "textarea", "label": "The feeling I keep struggling with"}, {"id": "f1", "type": "textarea", "label": "What my struggling looks like (fighting it, escaping it, analyzing it)"}, {"id": "f2", "type": "textarea", "label": "What happens to the feeling when I struggle"}, {"id": "f3", "type": "textarea", "label": "What lying back would look like for me"}, {"id": "f4", "type": "textarea", "label": "What my mind says will happen if I stop struggling"}, {"id": "f5", "type": "textarea", "label": "One place I will try lying back this week"}]'::jsonb, array['metaphor', 'acceptance', 'struggle']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('kind-hand-practice', 'Kind Hand Practice', 'act'::resource_kind, 'A brief self-compassion practice of placing a hand where the pain is and sending warmth through it.', 'Give the client a physical, wordless way to be kind to themselves in a hard moment.', array['Adults', 'Teens']::text[], '5 minutes', 'Do it in session first, with a feeling of moderate intensity. The client places a hand on the chest, stomach or wherever the feeling sits and lets warmth flow from the hand, as they would for a hurt child. Some clients find it awkward or even unbearable at first; that response is worth exploring gently rather than pushing past.', '[{"id": "f0", "type": "textarea", "label": "Where I placed my hand"}, {"id": "f1", "type": "textarea", "label": "What it was like to do this for myself"}, {"id": "f2", "type": "textarea", "label": "What came up that I did not expect"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend in this moment, and whether I could say it to myself"}, {"id": "f4", "type": "textarea", "label": "When I will use this in the week"}]'::jsonb, array['self-compassion', 'acceptance', 'mindfulness']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('dropping-anchor-practice', 'Dropping Anchor Practice', 'act'::resource_kind, 'A three-step grounding practice for emotional storms: acknowledge what is here, come back into the body, engage with the world.', 'Give the client a way to steady themselves in a storm without waiting for it to pass.', array['Adults', 'Teens', 'Children']::text[], '5 minutes to teach, then in the moment', 'Explain that an anchor does not make the storm go away; it holds you steady until it passes. Run it in session with a real feeling: name what is present, press feet into the floor and stretch, then notice five things in the room. Keep it to a minute or two so it fits real life, and repeat until it is a habit.', '[{"id": "f0", "type": "textarea", "label": "Acknowledge: what is showing up in me right now (thoughts, feelings, sensations)"}, {"id": "f1", "type": "textarea", "label": "Come back: what I did with my body (feet, hands, breath, stretch)"}, {"id": "f2", "type": "textarea", "label": "Engage: five things I noticed in the room"}, {"id": "f3", "type": "textarea", "label": "What changed, and what did not"}, {"id": "f4", "type": "textarea", "label": "A storm this week where I dropped anchor"}]'::jsonb, array['grounding', 'mindfulness', 'distress tolerance']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('mindfulness-what-and-how-log', 'Mindfulness What and How Log', 'dbt'::resource_kind, 'A daily record of one mindful activity, noting which what skill and which how skill were used.', 'Turn the DBT mindfulness skills from a list into a daily practice with specific instances.', array['Adults', 'Teens', 'Groups']::text[], 'One week', 'The what skills are observe, describe, participate; the how skills are non-judgmentally, one-mindfully, effectively. Have the client pick one of each per day and apply them to something ordinary like washing up or walking. The judgment column is where most clients discover how much commentary runs alongside their day.', '[{"id": "f0", "type": "textarea", "label": "Date and the activity"}, {"id": "f1", "type": "textarea", "label": "What skill I used (observe, describe, participate)"}, {"id": "f2", "type": "textarea", "label": "How skill I used (non-judgmentally, one-mindfully, effectively)"}, {"id": "f3", "type": "textarea", "label": "Judgments I noticed and let go of"}, {"id": "f4", "type": "textarea", "label": "How long I stayed with it before drifting"}, {"id": "f5", "type": "textarea", "label": "What I will try tomorrow"}]'::jsonb, array['mindfulness', 'skills', 'core DBT']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('validation-levels-practice', 'Validation Levels Practice', 'dbt'::resource_kind, 'Rewrites a recent reply to someone as a validating response, working up through the levels.', 'Teach the client to validate others, and themselves, as a skill rather than an instinct.', array['Adults', 'Teens', 'Groups']::text[], '20 minutes', 'Use a recent exchange where the client felt the conversation go wrong. Work up the levels: paying attention, reflecting back, reading the unspoken, validating in terms of history, validating in terms of the present, and radical genuineness. Then turn the same sheet inward on something the client has been invalidating in themselves.', '[{"id": "f0", "type": "textarea", "label": "What the other person said or did"}, {"id": "f1", "type": "textarea", "label": "What I actually replied"}, {"id": "f2", "type": "textarea", "label": "A reply that shows I was paying attention"}, {"id": "f3", "type": "textarea", "label": "A reply that reflects back what they said"}, {"id": "f4", "type": "textarea", "label": "A reply that makes sense of their reaction given their history or the situation"}, {"id": "f5", "type": "textarea", "label": "Something in myself I have been dismissing, and a validating sentence for it"}]'::jsonb, array['validation', 'interpersonal effectiveness', 'self-compassion']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('dialectical-thinking-sheet', 'Dialectical Thinking Sheet', 'dbt'::resource_kind, 'Takes an either-or judgment and finds the both-and that holds two truths at once.', 'Loosen black-and-white thinking by practicing the middle path on real examples.', array['Adults', 'Teens']::text[], '15 minutes', 'Start with the client''s own either-or statements: I am a failure or a success, they love me or they do not. Write the two truths side by side and join them with and rather than but. Model it in session with your own example. The doing prompt matters, since a dialectic that changes nothing is just a slogan.', '[{"id": "f0", "type": "textarea", "label": "An either-or judgment I have made this week"}, {"id": "f1", "type": "textarea", "label": "The truth on one side"}, {"id": "f2", "type": "textarea", "label": "The truth on the other side"}, {"id": "f3", "type": "textarea", "label": "Both together, joined with and"}, {"id": "f4", "type": "textarea", "label": "What changes in how I feel when I hold both"}, {"id": "f5", "type": "textarea", "label": "What I could do differently now that I hold both"}]'::jsonb, array['dialectics', 'thinking traps', 'middle path']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('willing-hands-practice', 'Willing Hands Practice', 'dbt'::resource_kind, 'A body posture of open, upturned hands practiced during moments of resistance or anger.', 'Change the emotion by changing the body, when the mind will not budge.', array['Adults', 'Teens', 'Children']::text[], '5 minutes', 'Teach it alongside half-smile: arms relaxed, hands open and palms up, whether standing, sitting or lying down. Practice with a mildly irritating memory and notice the shift, then assign it to real moments in the week. Clients often find the posture itself feels like giving in; that reaction is the willfulness the skill is for.', '[{"id": "f0", "type": "textarea", "label": "When I tried it in session, and what I noticed"}, {"id": "f1", "type": "textarea", "label": "The moments this week I most need it"}, {"id": "f2", "type": "textarea", "label": "What my hands were doing before"}, {"id": "f3", "type": "textarea", "label": "What happened when I turned them over"}, {"id": "f4", "type": "textarea", "label": "Where I used it this week, and the number before and after (0-10)"}]'::jsonb, array['acceptance', 'willingness', 'regulation']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('model-of-emotions-worksheet', 'Model of Emotions Worksheet', 'dbt'::resource_kind, 'Traces one emotion through the model: prompting event, interpretation, body response, urge, action and aftereffects.', 'Show the client the parts of an emotion so any part can become a place to intervene.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick a recent emotion of moderate strength and walk it through each box in order. Clients are often surprised by how much of the emotion is interpretation and how much is body. Ask which box a skill could go into; that decides whether the next step is check the facts, opposite action or self-soothing.', '[{"id": "f0", "type": "textarea", "label": "The emotion, and its intensity (0-100)"}, {"id": "f1", "type": "textarea", "label": "Prompting event"}, {"id": "f2", "type": "textarea", "label": "My interpretation of it"}, {"id": "f3", "type": "textarea", "label": "Body sensations and changes"}, {"id": "f4", "type": "textarea", "label": "The urge that came with it"}, {"id": "f5", "type": "textarea", "label": "What I actually did"}, {"id": "f6", "type": "textarea", "label": "The aftereffects (on me, on others, on the next hour)"}, {"id": "f7", "type": "textarea", "label": "Which box a skill could go into"}]'::jsonb, array['emotion regulation', 'formulation', 'skills']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('intimacy-map', 'Intimacy Map', 'couples'::resource_kind, 'Each partner rates closeness across several kinds of intimacy and says where they would like more.', 'Widen a couple''s idea of intimacy beyond the one kind they are arguing about.', array['Couples']::text[], '30 minutes', 'Cover emotional, physical, intellectual, playful, practical and spiritual intimacy, or whatever set fits the couple. Each rates now and wished-for on each kind, separately, then compare. The gaps that surprise each partner are the material; a couple stuck on one kind usually has another that has quietly worked.', '[{"id": "f0", "type": "textarea", "label": "Emotional closeness: now and wished-for (0-10)"}, {"id": "f1", "type": "textarea", "label": "Physical closeness: now and wished-for"}, {"id": "f2", "type": "textarea", "label": "Playfulness together: now and wished-for"}, {"id": "f3", "type": "textarea", "label": "Shared interests and conversation: now and wished-for"}, {"id": "f4", "type": "textarea", "label": "Practical teamwork: now and wished-for"}, {"id": "f5", "type": "textarea", "label": "The kind I most want more of, and what one step would look like"}, {"id": "f6", "type": "textarea", "label": "The kind that is quietly working, and what keeps it going"}]'::jsonb, array['intimacy', 'connection', 'relationship issues']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('household-fairness-audit', 'Household Fairness Audit', 'couples'::resource_kind, 'Each partner lists the household work they do, including the noticing and planning, before comparing lists.', 'Make the whole load visible so fairness can be discussed with facts instead of impressions.', array['Couples']::text[], '30 minutes', 'Lists are written separately and include the invisible work: remembering, anticipating, scheduling, deciding. Read them aloud without defending or correcting. Fairness is not necessarily fifty-fifty; the aim is that both feel the split is agreed rather than assumed. Choose one shift to try for a month.', '[{"id": "f0", "type": "textarea", "label": "Everything I do around the house, including the thinking work"}, {"id": "f1", "type": "textarea", "label": "What I did not know my partner did"}, {"id": "f2", "type": "textarea", "label": "What I would like taken off my plate"}, {"id": "f3", "type": "textarea", "label": "What I could take on"}, {"id": "f4", "type": "textarea", "label": "Where our sense of what is fair differs"}, {"id": "f5", "type": "textarea", "label": "One shift we agree to try this month"}]'::jsonb, array['fairness', 'communication', 'relationship issues']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('apology-language-sheet', 'Apology Language Sheet', 'couples'::resource_kind, 'Each partner spells out what an apology needs to contain for it to land with them.', 'Stop apologies bouncing off because each partner is apologizing the way they would want to receive one.', array['Couples']::text[], '25 minutes', 'Ask each partner for an apology that worked and one that did not, and pull out the ingredients: naming the hurt, taking responsibility, regret, repair, a plan. Partners often differ on which ingredient is essential. Rehearse one apology each in session, in the other''s language.', '[{"id": "f0", "type": "textarea", "label": "An apology I received that actually worked, and why"}, {"id": "f1", "type": "textarea", "label": "One that did not, and what was missing"}, {"id": "f2", "type": "textarea", "label": "What an apology needs to contain for me, in order of importance"}, {"id": "f3", "type": "textarea", "label": "What makes an apology worse for me (excuses, but, over-apologizing)"}, {"id": "f4", "type": "textarea", "label": "My partner''s ingredients, as I understood them"}, {"id": "f5", "type": "textarea", "label": "An apology I owe, written in their language"}]'::jsonb, array['repair', 'communication', 'relationship issues']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('individual-and-shared-goals-sheet', 'Individual and Shared Goals Sheet', 'couples'::resource_kind, 'Each partner names personal goals for the year, then the couple names shared ones and how each will support the other''s.', 'Keep each partner''s own growth alive inside the relationship instead of in competition with it.', array['Couples']::text[], '30 minutes', 'Individual goals come first and are not negotiated, only heard. Shared goals are built together. The support prompts are where the sheet earns its place: what each needs from the other to pursue their own goal, said out loud. Revisit at the half year.', '[{"id": "f0", "type": "textarea", "label": "My own goals for this year"}, {"id": "f1", "type": "textarea", "label": "What I need from my partner to pursue them"}, {"id": "f2", "type": "textarea", "label": "My partner''s goals, as I heard them"}, {"id": "f3", "type": "textarea", "label": "How I will support them"}, {"id": "f4", "type": "textarea", "label": "Our shared goals"}, {"id": "f5", "type": "textarea", "label": "The first shared step, and who does what"}, {"id": "f6", "type": "textarea", "label": "When we will check in on all of this"}]'::jsonb, array['goal setting', 'support', 'relationship issues']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('stress-signatures-sheet', 'Stress Signatures Sheet', 'couples'::resource_kind, 'Each partner describes how stress shows up in them and what actually helps, so the other can read the signs.', 'Replace guessing and taking it personally with a shared guide to each partner''s stress.', array['Couples']::text[], '25 minutes', 'Each partner writes their own signature: the early signs, the unhelpful things they do, what helps and what makes it worse. Then swap and read. Most couples discover that the thing one does to help is the thing the other finds worst. Agree a signal for I am stressed, not angry at you.', '[{"id": "f0", "type": "textarea", "label": "The early signs that I am stressed (body, mood, habits)"}, {"id": "f1", "type": "textarea", "label": "What I tend to do when stressed that is not helpful"}, {"id": "f2", "type": "textarea", "label": "What actually helps me"}, {"id": "f3", "type": "textarea", "label": "What makes it worse, even if it is well meant"}, {"id": "f4", "type": "textarea", "label": "Our signal for I am stressed, not angry at you"}, {"id": "f5", "type": "textarea", "label": "What I learned from my partner''s sheet"}]'::jsonb, array['stress', 'communication', 'relationship issues']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('brave-words-bank', 'Brave Words Bank', 'kids'::resource_kind, 'A child collects the things they can say to themselves when something feels scary or hard.', 'Give a child their own coping self-talk, in their words, ready before it is needed.', array['Children']::text[], '20 minutes', 'Collect the words from moments the child has already been brave; ask what they said to themselves then. Add a few from a favorite character or a grown-up they trust. Write them on cards or a poster the child decorates, and have the parent say one back to the child in the moment, not a lecture.', '[{"id": "f0", "type": "textarea", "label": "A time I was brave, and what I said to myself"}, {"id": "f1", "type": "textarea", "label": "Words a favorite character would say"}, {"id": "f2", "type": "textarea", "label": "Words my grown-up says that help"}, {"id": "f3", "type": "textarea", "label": "My top three brave words"}, {"id": "f4", "type": "textarea", "label": "Where my brave words will live"}, {"id": "f5", "type": "textarea", "label": "A time this week I used them"}]'::jsonb, array['self-talk', 'children', 'anxiety', 'coping skills']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('social-story-builder', 'Social Story Builder', 'kids'::resource_kind, 'A short, first-person story that walks a child through an upcoming situation step by step.', 'Take the unknown out of a new or hard situation by rehearsing it in a story the child helps write.', array['Children']::text[], '25 minutes', 'Write it with the child in the first person and present tense: I walk into the classroom, I find my seat. Include what the child might feel and what they can do, and keep the tone matter-of-fact. Read it daily in the run-up with a parent, and let the child illustrate it. Update it once the real thing has happened.', '[{"id": "f0", "type": "textarea", "label": "The situation my story is about"}, {"id": "f1", "type": "textarea", "label": "What happens first, then next, then next"}, {"id": "f2", "type": "textarea", "label": "What I might feel, and what I can do about it"}, {"id": "f3", "type": "textarea", "label": "What the grown-ups will be doing"}, {"id": "f4", "type": "textarea", "label": "How the story ends"}, {"id": "f5", "type": "textarea", "label": "When we will read it, and who with"}, {"id": "f6", "type": "textarea", "label": "What really happened, to add to the story"}]'::jsonb, array['routines', 'children', 'anxiety', 'psychoeducation']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('five-senses-hunt-card', 'Five Senses Hunt Card', 'kids'::resource_kind, 'A grounding activity turned into a hunt: find five things to see, four to touch, three to hear, two to smell, one to taste.', 'Teach a child to come back to the room through their senses, as a game they can play anywhere.', array['Children', 'Teens']::text[], '10 minutes', 'Play it in session with real objects and then in different rooms so it generalizes. Make the card the child''s own, with drawings for each sense. Parents run it during big feelings by playing, not instructing: I bet you cannot find four things to touch. Keep a pocket version for school.', '[{"id": "f0", "type": "textarea", "label": "Five things I can see"}, {"id": "f1", "type": "textarea", "label": "Four things I can touch"}, {"id": "f2", "type": "textarea", "label": "Three things I can hear"}, {"id": "f3", "type": "textarea", "label": "Two things I can smell"}, {"id": "f4", "type": "textarea", "label": "One thing I can taste"}, {"id": "f5", "type": "textarea", "label": "How my body felt before and after"}, {"id": "f6", "type": "textarea", "label": "A place I could play this when I feel wobbly"}]'::jsonb, array['grounding', 'children', 'coping skills', 'sensory']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('change-warning-chart', 'Change Warning Chart', 'kids'::resource_kind, 'A visual countdown a parent uses before transitions, with the child''s chosen warning times and words.', 'Reduce meltdowns at transitions by making the change visible before it arrives.', array['Children']::text[], '20 minutes to set up, then daily', 'Transitions are where many children''s hardest moments happen. Build the chart with the child: which changes are hardest, how many warnings they want, and the words that work. The parent gives the warnings the same way every time, with a visible timer where possible. Review the hardest transition after a week.', '[{"id": "f0", "type": "textarea", "label": "The changes that are hardest for me (stopping play, leaving, bedtime, screens off)"}, {"id": "f1", "type": "textarea", "label": "How many warnings I want, and when (ten minutes, five, one)"}, {"id": "f2", "type": "textarea", "label": "The words my grown-up will use"}, {"id": "f3", "type": "textarea", "label": "What I can do in the last minute to get ready"}, {"id": "f4", "type": "textarea", "label": "What helps after the change"}, {"id": "f5", "type": "textarea", "label": "How the week''s hardest change went"}]'::jsonb, array['transitions', 'children', 'routines', 'parenting']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('parent-coaching-sheet-emotion-coaching', 'Parent Coaching Sheet: Emotion Coaching', 'kids'::resource_kind, 'The five steps of emotion coaching for a parent to practice on one moment a day.', 'Help a parent meet a child''s feeling before dealing with the behavior.', array['Adults']::text[], '15 minutes to teach, then daily', 'The steps are notice the feeling, see it as a chance to connect, listen and validate, name the feeling, and then set limits and problem-solve. Parents usually skip to the last step, so rehearse the middle three in session with a recent example. One coached moment a day is enough to start.', '[{"id": "f0", "type": "textarea", "label": "The moment I chose today"}, {"id": "f1", "type": "textarea", "label": "The feeling I noticed in my child"}, {"id": "f2", "type": "textarea", "label": "What I said to show I was listening"}, {"id": "f3", "type": "textarea", "label": "The feeling word I offered"}, {"id": "f4", "type": "textarea", "label": "The limit I set, after all that"}, {"id": "f5", "type": "textarea", "label": "What I found hardest (usually waiting before the limit)"}, {"id": "f6", "type": "textarea", "label": "How my child responded"}]'::jsonb, array['parenting', 'emotion coaching', 'children']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('mindful-listening-telephone', 'Mindful Listening Telephone', 'game'::resource_kind, 'A message passed around the circle, but each player must repeat it back to the sender exactly before passing it on.', 'Make listening a skill players practice under pressure and laughter.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'Start with short messages and lengthen them. A player who repeats it wrong starts the message again from the sender. Round two uses feelings messages: I felt left out when the game changed. The debrief asks what it was like to be repeated back accurately, which is the point.', '[{"id": "f0", "type": "textarea", "label": "Messages we passed"}, {"id": "f1", "type": "textarea", "label": "Where the message broke down, and why"}, {"id": "f2", "type": "textarea", "label": "What it felt like to be repeated back exactly"}, {"id": "f3", "type": "textarea", "label": "A feelings message I sent"}, {"id": "f4", "type": "textarea", "label": "One thing I will do differently when listening this week"}]'::jsonb, array['listening', 'group', 'play', 'communication']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('yes-and-improv-warm-up', 'Yes, And Improv Warm-Up', 'game'::resource_kind, 'Partners build a scene one line at a time, each accepting what the other offered and adding to it.', 'Practice acceptance and flexibility in a playful form before applying them to real life.', array['Teens', 'Adults', 'Groups']::text[], '15 minutes', 'The only rule is that no offer is refused: every line begins by accepting what came before, then adds. Play a round with yes, but first so the group feels the difference. The debrief connects it to life: where the client says no to what is already true, and what yes, and would look like there.', '[{"id": "f0", "type": "textarea", "label": "A scene we built"}, {"id": "f1", "type": "textarea", "label": "What happened when someone said yes, but"}, {"id": "f2", "type": "textarea", "label": "What it felt like to have my idea accepted and built on"}, {"id": "f3", "type": "textarea", "label": "Where in my life I say no to what is already the case"}, {"id": "f4", "type": "textarea", "label": "What yes, and would sound like there"}]'::jsonb, array['flexibility', 'acceptance', 'group', 'play']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('skill-spinner', 'Skill Spinner', 'game'::resource_kind, 'A spinner or die assigns a coping skill; the player demonstrates it on the spot for a situation card.', 'Get coping skills rehearsed out loud and on the body rather than remembered as names.', array['Children', 'Teens', 'Groups']::text[], '20 minutes', 'Fill the spinner with skills the group has actually learned. A player spins, draws a situation, and shows the skill for that situation, with the group judging whether it fits. Misfits are the best teaching moments: a breathing skill spun for a bullying situation opens a conversation about which skill would do.', '[{"id": "f0", "type": "textarea", "label": "Skills on our spinner"}, {"id": "f1", "type": "textarea", "label": "The skill I spun, and the situation I drew"}, {"id": "f2", "type": "textarea", "label": "Whether it fit, and what would have fit better"}, {"id": "f3", "type": "textarea", "label": "A skill I saw someone else demonstrate well"}, {"id": "f4", "type": "textarea", "label": "The skill I will practice this week"}]'::jsonb, array['coping skills', 'play', 'group']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('feelings-color-draw', 'Feelings Color Draw', 'game'::resource_kind, 'Players draw a colored card and name a feeling that color is for them, then a time they felt it.', 'Reach feelings through color for players who do not yet have the words.', array['Children', 'Teens', 'Groups']::text[], '15 minutes', 'There are no right answers about which color is which feeling, and the differences between players are worth noticing aloud. A second round asks where in the body the feeling lives. Works well with children who freeze when asked how they feel directly, and as a warm-up for groups.', '[{"id": "f0", "type": "textarea", "label": "The colors I drew, and the feelings I gave them"}, {"id": "f1", "type": "textarea", "label": "A time I felt one of them"}, {"id": "f2", "type": "textarea", "label": "A color someone else gave a different feeling to"}, {"id": "f3", "type": "textarea", "label": "Where in my body one of my feelings lives"}, {"id": "f4", "type": "textarea", "label": "The color I would choose for how I feel right now"}]'::jsonb, array['emotion identification', 'play', 'children', 'group']::text[], '2026-09-14T15:00:00+00:00'::timestamptz),
  ('what-would-you-do-scenario-cards', 'What Would You Do? Scenario Cards', 'game'::resource_kind, 'Scenario cards describing a tricky social or emotional moment, with players giving and then debating their responses.', 'Rehearse decisions in hard moments while the stakes are only a card.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Write the scenarios with the group so they are real to them: a friend shares a secret that worries you, someone laughs at your answer, a parent breaks a promise. Each player answers, then the group discusses; there is rarely one right answer, and saying so is part of the game. Keep a few cards for the situations the group finds hardest.', '[{"id": "f0", "type": "textarea", "label": "Scenarios we wrote"}, {"id": "f1", "type": "textarea", "label": "The card I drew, and what I said I would do"}, {"id": "f2", "type": "textarea", "label": "An answer from someone else I had not thought of"}, {"id": "f3", "type": "textarea", "label": "A scenario the group found hardest"}, {"id": "f4", "type": "textarea", "label": "What I would actually do if it happened this week"}]'::jsonb, array['decisions', 'play', 'group', 'social skills']::text[], '2026-09-14T15:00:00+00:00'::timestamptz)
